function statics(pcx){
  const out = pcx.text.grep('static "', { max: 600 })
  const arr = []
  for (const line of out.split("\n")) {
    const m = line.match(/static "((?:[^"\\]|\\.)*)"/)
    if (m) arr.push(m[1])
  }
  return arr
}
function extract(pcx){
  const s = statics(pcx)
  const keys = ["eval/success_rate","eval/reward_mean","eval/episode_length","train/reward_mean","train/entropy","critic/explained_variance","train/kl_divergence","train/clip_fraction","train/policy_loss","train/value_loss",
    "algorithm","batch_size","clip_range","ent_coef","env","gae_lambda","gamma","learning_rate","lr_schedule","n_epochs","n_steps","seed","total_timesteps","version","warmup_steps","tau","auto_alpha","policy_delay"]
  const o = {}
  for (let i=0;i<s.length;i++){
    if (keys.includes(s[i]) && s[i+1]!==undefined && !(s[i] in o)) o[s[i]] = s[i+1]
  }
  o._name = s.find(t => /^(antmaze|debug|hopper|halfcheetah)/.test(t)) || null
  o._state = s.find(t => /^(finished|running|crashed|failed)$/.test(t)) || null
  return o
}
