function extract2(pcx){
  const s = statics(pcx)
  const keys = ["eval/success_rate","eval/reward_mean","eval/episode_length","train/reward_mean","train/entropy","critic/explained_variance","train/kl_divergence","train/clip_fraction","train/policy_loss","train/value_loss","learning_rate",
    "algorithm","batch_size","clip_range","ent_coef","env","gae_lambda","gamma","lr_schedule","n_epochs","n_steps","seed","total_timesteps","version","warmup_steps","tau","auto_alpha","policy_delay","Run ID","gitCommit"]
  const o = {}
  for (let i=0;i<s.length;i++){
    if (keys.includes(s[i]) && s[i+1]!==undefined && !(s[i] in o)) o[s[i]] = s[i+1]
  }
  // summary learning_rate appears before config; capture both occurrences
  const lrIdx = s.map((v,i)=>v==="learning_rate"?i:-1).filter(i=>i>=0)
  if (lrIdx.length>1) { o["lr_summary"] = s[lrIdx[0]+1]; o["learning_rate"] = s[lrIdx[lrIdx.length-1]+1] }
  o.name = s.find(t => t.length>18 && /^(antmaze|debug|hopper|halfcheetah)/.test(t)) || null
  const st = s.find(t => /^(finished|running|crashed|failed)$/.test(t)); o.state = st||null
  const ni = s.indexOf(o.state); o.dur = ni>=0 ? s[ni+1] : null; o.created = ni>=0 ? s[ni+2] : null
  return o
}
