async function readRunFull(n){
  await machine.press({ key: 'l', ctrl: true }); await wait({ waitTime: 0.6 })
  await machine.type({ text: `wandb.web.hku.icu/mllab-team/antmaze-rl-benchmark/runs/run-${n}/overview`, withReturn: true })
  await wait({ waitTime: 3 })
  const top = statics(await machine.pageContent())
  for (let k=0;k<7;k++){ await machine.scroll({ x: 540, y: 800 }) }
  await wait({ waitTime: 1.2 })
  const bot = statics(await machine.pageContent())
  const s = top.concat(bot)
  const keys = ["eval/success_rate","eval/reward_mean","eval/episode_length","train/reward_mean","train/entropy","critic/explained_variance","train/kl_divergence","train/clip_fraction","train/policy_loss","train/value_loss",
    "algorithm","batch_size","clip_range","ent_coef","env","gae_lambda","gamma","lr_schedule","n_epochs","n_steps","seed","total_timesteps","version","warmup_steps","tau","auto_alpha","policy_delay","Run ID","gitCommit","train/alpha","train/actor_loss","train/critic_loss"]
  const o = {}
  for (let i=0;i<s.length;i++){ if (keys.includes(s[i]) && s[i+1]!==undefined && !(s[i] in o)) o[s[i]] = s[i+1] }
  const bc = top.lastIndexOf("/"); o.name = bc>=0 ? top[bc+1] : null
  o.state = top[bc+2]; o.dur = top[bc+3]; o.created = top[bc+4]
  const lrAll = s.map((v,i)=>v==="learning_rate"?i:-1).filter(i=>i>=0).map(i=>s[i+1])
  o.lr_values = Array.from(new Set(lrAll))
  const tagStart = top.indexOf("Tags"); o.tags = tagStart>=0 ? top.slice(tagStart+1, top.indexOf("Notes")).filter(t=>t!=="+ Add") : []
  return o
}
